import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

function AdminIndexPage() {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    const [username] = useState(storedUser?.username || "Admin");
    const [stats, setStats] = useState({
        totalUsers: 0,
        totalStudies: 0,
        activeStudies: 0,
        totalArtifacts: 0
    });
    const [recentActivities, setRecentActivities] = useState([]);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        document.body.style.margin = "0";
        document.body.style.padding = "0";
        document.documentElement.style.margin = "0";
        document.documentElement.style.padding = "0";
        document.body.style.backgroundColor = "black";
    }, []);

    useEffect(() => {
        const fetchAdminData = async () => {
            try {
                const token = localStorage.getItem("token");

                // Fetch admin statistics
                const statsResponse = await fetch("http://localhost:8080/api/admin/stats", {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                });

                if (statsResponse.ok) {
                    const statsData = await statsResponse.json();
                    setStats(statsData);
                }

                // Fetch recent activities
                const activitiesResponse = await fetch("http://localhost:8080/api/admin/recent-activities", {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                });

                if (activitiesResponse.ok) {
                    const activitiesData = await activitiesResponse.json();
                    const sorted = activitiesData
                        .sort((a, b) => {
                            const dateA = new Date(a.createdAt || a.timestamp);
                            const dateB = new Date(b.createdAt || b.timestamp);
                            return dateB - dateA;
                        })
                        .slice(0, 3);

                    setRecentActivities(sorted);
                }
            } catch (error) {
                console.error("❌ Error fetching admin data:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchAdminData();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem("token");
        localStorage.removeItem("user");
        navigate("/");
    };

    const handleMyProfile = () => navigate("/profile");
    const handleManageUsers = () => navigate("/admin/users");
    const handleManageStudies = () => navigate("/admin/studies");
    const handleManageArtifacts = () => navigate("/admin/artifacts");

    const getStyleByActivityType = (type) => {
        switch (type?.toUpperCase()) {
            case "USER_REGISTERED":
                return { border: "#22c55e", badgeBg: "rgba(34,197,94,0.2)", badgeColor: "#4ade80" };
            case "STUDY_CREATED":
                return { border: "#3b82f6", badgeBg: "rgba(59,130,246,0.2)", badgeColor: "#60a5fa" };
            case "ARTIFACT_UPLOADED":
                return { border: "#a78bfa", badgeBg: "rgba(167,139,250,0.2)", badgeColor: "#c4b5fd" };
            case "STUDY_COMPLETED":
                return { border: "#facc15", badgeBg: "rgba(250,204,21,0.2)", badgeColor: "#fde047" };
            case "USER_DELETED":
                return { border: "#ef4444", badgeBg: "rgba(239,68,68,0.2)", badgeColor: "#f87171" };
            case "STUDY_ARCHIVED":
                return { border: "#d1d5db", badgeBg: "rgba(255,255,255,0.15)", badgeColor: "#f3f4f6" };
            default:
                return { border: "#60a5fa", badgeBg: "rgba(96,165,250,0.2)", badgeColor: "#93c5fd" };
        }
    };

    return (
        <div style={styles.container}>

            {/* PARTICLES */}
            <div style={styles.particles}>
                {[...Array(55)].map((_, i) => {
                    const startY = Math.random() * 100;
                    const negDelay = -(Math.random() * 15).toFixed(2);

                    return (
                        <div
                            key={i}
                            style={{
                                ...styles.particle,
                                left: `${Math.random() * 100}%`,
                                top: `${startY}vh`,
                                animationDelay: `${negDelay}s`,
                                animationDuration: `${16 + Math.random() * 10}s`,
                                opacity: 0.45,
                            }}
                        />
                    );
                })}
            </div>

            {/* Navbar */}
            <div style={styles.navbar}>
                <h2 style={styles.title}>Admin Dashboard</h2>
                <div style={styles.right}>
                    <span style={styles.userText}>{username}</span>

                    <button style={styles.profileButton} onClick={handleManageArtifacts}>
                        Manage Artifacts
                    </button>

                    <button style={styles.profileButton} onClick={handleMyProfile}>
                        My Profile
                    </button>

                    <button
                        style={styles.profileButton}
                        onClick={() => navigate("/admin/reports")}
                    >
                        Reports
                    </button>

                    <button
                        className="logout-btn"
                        style={styles.logout}
                        onClick={handleLogout}
                    >
                        Logout
                    </button>
                </div>
            </div>

            {/* Main Content */}
            <div style={styles.mainContent}>
                <div style={styles.welcomeSection}>
                    <h1 style={styles.welcomeTitle}>Welcome to Admin Control Panel</h1>
                    <p style={styles.welcomeText}>
                        Monitor system activities, manage users and studies, and oversee all platform operations.
                    </p>
                </div>

                {/* Statistics Overview Cards */}
                <div style={styles.statsSection}>
                    <h2 style={styles.sectionTitle}>Platform Statistics</h2>
                    <div style={styles.statsGrid}>
                        <div
                            style={{
                                ...styles.statCard,
                                border: "1px solid #22c55e",
                                boxShadow: "0 0 6px #22c55e55"
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.transform = "translateY(-5px)";
                                e.currentTarget.style.boxShadow = "0 0 20px #22c55e88";
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.transform = "translateY(0)";
                                e.currentTarget.style.boxShadow = "0 0 6px #22c55e55";
                            }}
                        >
                            <div style={styles.statIcon}>👥</div>
                            <h3 style={styles.statNumber}>{stats.totalUsers}</h3>
                            <p style={styles.statLabel}>Total Users</p>
                        </div>

                        <div
                            style={{
                                ...styles.statCard,
                                border: "1px solid #3b82f6",
                                boxShadow: "0 0 6px #3b82f655"
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.transform = "translateY(-5px)";
                                e.currentTarget.style.boxShadow = "0 0 20px #3b82f688";
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.transform = "translateY(0)";
                                e.currentTarget.style.boxShadow = "0 0 6px #3b82f655";
                            }}
                        >
                            <div style={styles.statIcon}>📊</div>
                            <h3 style={styles.statNumber}>{stats.totalStudies}</h3>
                            <p style={styles.statLabel}>Total Studies</p>
                        </div>

                        <div
                            style={{
                                ...styles.statCard,
                                border: "1px solid #facc15",
                                boxShadow: "0 0 6px #facc1555"
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.transform = "translateY(-5px)";
                                e.currentTarget.style.boxShadow = "0 0 20px #facc1588";
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.transform = "translateY(0)";
                                e.currentTarget.style.boxShadow = "0 0 6px #facc1555";
                            }}
                        >
                            <div style={styles.statIcon}>⚡</div>
                            <h3 style={styles.statNumber}>{stats.activeStudies}</h3>
                            <p style={styles.statLabel}>Active Studies</p>
                        </div>

                        <div
                            style={{
                                ...styles.statCard,
                                border: "1px solid #a78bfa",
                                boxShadow: "0 0 6px #a78bfa55"
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.transform = "translateY(-5px)";
                                e.currentTarget.style.boxShadow = "0 0 20px #a78bfa88";
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.transform = "translateY(0)";
                                e.currentTarget.style.boxShadow = "0 0 6px #a78bfa55";
                            }}
                        >
                            <div style={styles.statIcon}>📁</div>
                            <h3 style={styles.statNumber}>{stats.totalArtifacts}</h3>
                            <p style={styles.statLabel}>Total Artifacts</p>
                        </div>
                    </div>
                </div>

                {/* Action Buttons */}
                <div style={styles.actionButtons}>
                    <button
                        style={styles.primaryButton}
                        onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.05)")}
                        onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1.0)")}
                        onClick={handleManageUsers}
                    >
                        <span style={styles.buttonIcon}>👥</span>Manage Users
                    </button>

                    <button
                        style={styles.secondaryButton}
                        onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.05)")}
                        onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1.0)")}
                        onClick={handleManageStudies}
                    >
                        <span style={styles.buttonIcon}>📚</span>Manage Studies
                    </button>
                </div>

                {/* Recent Platform Activities */}
                <div style={styles.recentSection}>
                    <h2 style={styles.sectionTitle}>Recent Platform Activities</h2>

                    {loading ? (
                        <p style={styles.loadingText}>Loading recent activities...</p>
                    ) : recentActivities.length === 0 ? (
                        <p style={styles.emptyText}>No recent activities found on the platform.</p>
                    ) : (
                        <div style={styles.studiesGrid}>
                            {recentActivities.map((activity, index) => {
                                const theme = getStyleByActivityType(activity.type);
                                return (
                                    <div
                                        key={activity.id || index}
                                        style={{
                                            ...styles.studyCard,
                                            border: `1px solid ${theme.border}`,
                                            boxShadow: `0 0 6px ${theme.border}55`,
                                        }}
                                    >
                                        <div style={styles.studyHeader}>
                                            <h3 style={styles.studyTitle}>
                                                {activity.title || activity.description || "Platform Activity"}
                                            </h3>

                                            <span
                                                style={{
                                                    ...styles.statusBadge,
                                                    background: theme.badgeBg,
                                                    color: theme.badgeColor,
                                                }}
                                            >
                                                {activity.type}
                                            </span>

                                            {activity.visibility && (
                                                <span style={styles.visibilityBadge}>
                                                    {activity.visibility}
                                                </span>
                                            )}
                                        </div>

                                        <p style={styles.studyDescription}>
                                            {activity.details || activity.description || "Activity details not available"}
                                        </p>

                                        <div style={styles.dateRow}>
                                            <span>
                                                User: {activity.username || activity.user || "System"}
                                            </span>
                                            <span>
                                                {new Date(
                                                    activity.createdAt || activity.timestamp || Date.now()
                                                ).toLocaleDateString()}
                                            </span>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {/* Footer */}
            <footer style={styles.footer}>
                © {new Date().getFullYear()} Artifact Comparator — Admin Panel
            </footer>

            {/* Particle Animation */}
            <style>{`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: 0.4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }

                /* 🔥 Red Glow Hover for Logout */
                .logout-btn:hover {
                    transform: scale(1.06);
                    box-shadow: 0 0 18px rgba(239,68,68,0.7);
                    border-color: rgba(239,68,68,0.85) !important;
                }
            `}</style>
        </div>
    );
}

